window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["agent-frameworks"]={"title":"智能体框架：抽象运行循环，但不外包正确性与控制权","subtitle":"从模型适配、工具注册、状态图、持久化和追踪，到抽象泄漏、版本迁移与逃生口，判断何时框架值得引入。","thesis":"框架减少模型调用、工具适配、状态保存和观测的样板代码；它不会替你定义任务成功、权限、幂等或恢复。框架越厚，越要把<b>领域状态、验收与可移植测试</b>留在框架之外。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"从手写客服循环到持久状态图","rule":"中途杀进程，验证从批准前状态恢复且不重复退款","steps":"先复现原轨迹，再杀进程验证不重复退款","interpretation":"图画得漂亮不是验收"}}],"formulas":[{"id":"agent-framework-tco","section":9,"formulaIndex":1,"symbols":[{"name":"TCO","meaning":"选定时间范围内使用框架的总拥有成本","evidence":"TCO 是选定时间范围内的总拥有成本"},{"name":"C","meaning":"开发、运行、诊断、迁移或锁定中的一项成本","evidence":"分别是初始开发、日常运行、故障诊断、升级迁移和供应商锁定成本"}]}],"termReviews":[{"section":2,"reviewedAt":"2026-07-27","terms":[{"name":"trace","meaning":"把一次任务中的模型、工具、状态和错误事件串联起来的追踪记录","purpose":"定位失败发生在哪个运行环节","definitionEvidence":"trace、队列、评测","purposeEvidence":"观测部署五层责任"}]},{"section":4,"reviewedAt":"2026-07-27","terms":[{"name":"领域状态","meaning":"由业务自己定义并版本化的对象和流程事实","purpose":"避免核心业务语义被框架消息格式锁定","definitionEvidence":"领域状态设计输入订单","purposeEvidence":"独立于框架消息"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"智能体框架封装模型工具状态和追踪的运行时。","evidence":"智能体框架是把模型调用、工具循环、状态保存和追踪封装成运行时的开发组件"},"problem":{"answer":"它减少 Agent 最小循环的重复样板代码。","evidence":"减少实现摩擦"},"inputOutput":{"answer":"输入最小循环与痛点，输出运行时能力。","evidence":"输入是已理解的最小 Agent 循环和具体工程痛点，输出是较少样板代码及可选路由、检查点和观测能力"},"mechanism":{"answer":"把循环步骤产品化并增加可选横切能力。","evidence":"框架把这些步骤产品化"},"interpretation":{"answer":"框架价值是实现摩擦减少而非任务自动正确。","evidence":"它减少实现摩擦，不定义业务成功"},"boundary":{"answer":"需求不清时厚框架只会隐藏调用栈。","evidence":"需求不清时厚框架只会隐藏调用栈"}},{"section":2,"definition":{"answer":"框架能力分模型循环状态生态和观测五层。","evidence":"输出模型适配、运行循环、状态图、扩展生态和观测部署五层责任"},"problem":{"answer":"它解决不同产品都声称支持 Agent 时怎样比较。","evidence":"“支持 Agent”可能只支持模型接口，也可能包含持久工作流，怎样比较"},"inputOutput":{"answer":"输入候选框架能力，输出五层责任。","evidence":"输入候选产品能力，输出模型适配、运行循环、状态图、扩展生态和观测部署五层责任"},"mechanism":{"answer":"逐层核对职责与不应外包的业务决定。","evidence":"逐层比较可避免把“支持 Agent”当成同一能力"},"interpretation":{"answer":"层级覆盖多不表示更适合生产。","evidence":"层级覆盖越多不表示越适合生产"},"boundary":{"answer":"目标权限语义指标仍由业务拥有。","evidence":"业务仍须自己拥有目标、权限、领域语义和价值指标"}},{"section":3,"definition":{"answer":"客服案例展示手写循环何时迁移到持久状态图。","evidence":"从手写客服循环到持久状态图"},"problem":{"answer":"它解决增加框架何时比继续写条件分支更清楚。","evidence":"什么时候“加一个框架”比继续写 if/else 更清楚"},"inputOutput":{"answer":"输入审批回调恢复权限，输出领域状态和状态图。","evidence":"输入手写循环、退款审批、跨天回调、恢复和租户权限，输出版本化领域状态与持久状态图"},"mechanism":{"answer":"复现旧轨迹后注入崩溃并验证不重复退款。","evidence":"先复现原轨迹，再杀进程验证不重复退款"},"interpretation":{"answer":"恢复和诊断改善才证明迁移价值。","evidence":"只有在恢复或诊断改善时才证明价值"},"boundary":{"answer":"图画漂亮不等于框架迁移通过。","evidence":"图画得漂亮不是验收"}},{"section":4,"definition":{"answer":"领域状态是独立于框架消息的版本化业务事实。","evidence":"领域状态设计输入订单"},"problem":{"answer":"它避免把业务对象塞入消息后锁死迁移。","evidence":"为什么把全部业务数据塞进框架 message 列表会锁死迁移"},"inputOutput":{"answer":"输入业务对象版本，输出 schema 和迁移记录。","evidence":"输入订单、批准、证据、幂等键和版本，输出独立于框架消息的 schema 与迁移记录"},"mechanism":{"answer":"消息从状态派生，检查点存版本，分支明确归并。","evidence":"消息从状态派生"},"interpretation":{"answer":"框架消息只是领域状态的一个视图。","evidence":"框架消息只是一个视图"},"boundary":{"answer":"它不能成为唯一真相或跨租户共享字典。","evidence":"不能成为业务唯一真相或跨租户共享字典"}},{"section":5,"definition":{"answer":"分层架构把应用控制框架运行时和外部系统分开。","evidence":"输出可替换的责任边界"},"problem":{"answer":"它说明哪些层可替换哪些必须由应用拥有。","evidence":"哪一层应该能被替换，哪一层必须由应用自己拥有"},"inputOutput":{"answer":"输入三层组件，输出可替换责任边界。","evidence":"输入应用领域控制、框架运行时和外部模型工具存储，输出可替换的责任边界"},"mechanism":{"answer":"应用持有目标权限验收，框架承载循环和观测。","evidence":"应用拥有目标、权限、验收和 schema"},"interpretation":{"answer":"可替换表示接口和测试隔离良好。","evidence":"可替换表示接口与测试隔离良好"},"boundary":{"answer":"它不表示任意框架可无损互换。","evidence":"不表示任意框架可无损互换"}},{"section":6,"definition":{"answer":"可靠性语义显式规定重试取消和终止。","evidence":"重试、取消和终止语义必须可见"},"problem":{"answer":"它防止框架自动重试悄悄重复副作用。","evidence":"为什么可能悄悄重复副作用"},"inputOutput":{"answer":"输入调用错误预算取消，输出重试查询或停止。","evidence":"输入调用类型、错误、幂等键、预算和取消信号，输出重试、查询、取消或终止"},"mechanism":{"answer":"按调用类型有界重试，写操作先查询去重。","evidence":"写工具先查询结果并去重"},"interpretation":{"answer":"自动重试只表示再次调度。","evidence":"框架自动重试只表示再次调度"},"boundary":{"answer":"它可能放大永久错误和副作用。","evidence":"可能放大永久错误和副作用"}},{"section":7,"definition":{"answer":"抽象逃生口保留供应商原始事件和直接调用路径。","evidence":"输出可诊断差异与直接调用路径"},"problem":{"answer":"它解决统一模型接口遮蔽新能力和错误细节。","evidence":"解决统一接口遮蔽新能力和错误细节的问题"},"inputOutput":{"answer":"输入原始与适配结果，输出差异和逃生口。","evidence":"输入供应商原始请求响应、扩展字段和框架适配结果，输出可诊断差异与直接调用路径"},"mechanism":{"answer":"对照原始事件并允许绕过最低公分母适配器。","evidence":"保留原始请求响应"},"interpretation":{"answer":"接口一致不表示语义等价。","evidence":"接口一致不等于语义等价"},"boundary":{"answer":"更换适配器必须重跑任务安全成本评测。","evidence":"必须重跑任务、安全和成本评测"}},{"section":8,"definition":{"answer":"插件治理审查连接器代码依赖权限和提示。","evidence":"插件治理输入连接器代码"},"problem":{"answer":"它处理社区工具包等于执行第三方代码的风险。","evidence":"为何可能等于执行第三方代码"},"inputOutput":{"answer":"输入插件依赖凭证，输出允许限制锁定或拒绝。","evidence":"输入连接器代码、依赖、权限、提示和生产凭证，输出允许、沙箱限制、版本锁定或拒绝"},"mechanism":{"answer":"逐工具允许并审计升级默认值。","evidence":"逐工具允许并审计升级默认值"},"interpretation":{"answer":"安装成功不表示供应链可信。","evidence":"安装成功或来源流行不表示供应链可信"},"boundary":{"answer":"生产凭证和运行权限必须最小化。","evidence":"开发/生产凭证"}},{"section":9,"definition":{"answer":"选型实验比较框架总拥有成本与故障表现。","evidence":"输出同预算质量、延迟、恢复和 TCO"},"problem":{"answer":"它解决节省开发时间是否被长期成本抵消。","evidence":"让每月升级和故障排查增加多少成本"},"inputOutput":{"answer":"输入任务框架五类成本，输出质量恢复和 TCO。","evidence":"输入代表任务、候选框架和初始开发、运行、诊断、迁移、锁定五类成本，输出同预算质量、延迟、恢复和 TCO"},"mechanism":{"answer":"限定时间试验并注入崩溃人工中断。","evidence":"time-box 实验注入崩溃与人工中断"},"interpretation":{"answer":"TCO 是决策框架而非精确预测。","evidence":"TCO 是决策框架而非精确预测"},"boundary":{"answer":"权重与时间范围必须按团队实际估计。","evidence":"必须按团队实际估计"}},{"section":10,"definition":{"answer":"迁移契约测试比较框架升级前后的事件和副作用。","evidence":"迁移契约测试输入冻结的状态"},"problem":{"answer":"它防止大版本升级悄悄改变关键行为。","evidence":"哪些行为最容易悄悄变化"},"inputOutput":{"answer":"输入冻结轨迹，输出新旧事件副作用差异。","evidence":"输入冻结的状态、工具序列、权限拒绝、人工暂停、超时、恢复和业务结果，输出旧版与新版的事件及副作用差异"},"mechanism":{"answer":"先迁移 schema，再分开实例并灰度观察。","evidence":"先迁移 schema，再分开运行新旧实例并灰度观察"},"interpretation":{"answer":"文本措辞可以变化但控制边界不得变化。","evidence":"自然语言不必逐字相同"},"boundary":{"answer":"权限状态副作用不能静默变化。","evidence":"不得静默变化"}},{"section":12,"definition":{"answer":"逐层购买抽象按真实需求组合最薄组件。","evidence":"自建与引入不是二选一，而是逐层购买抽象"},"problem":{"answer":"它解决只需追踪时是否必须采用完整框架。","evidence":"是否必须采用完整Agent框架"},"inputOutput":{"answer":"输入需求组件信号，输出最薄抽象组合。","evidence":"输入真实需求、已有组件和升级信号，输出 SDK、追踪、队列、状态图等最薄组合"},"mechanism":{"answer":"先购横切能力，重复出现恢复路由才加厚。","evidence":"只有恢复、中断或图路由反复出现才加厚运行时"},"interpretation":{"answer":"混合方案表示责任可以拆分。","evidence":"混合自建与引入表示责任可拆分"},"boundary":{"answer":"不能没有退出条件地因惯性扩张。","evidence":"不允许框架因惯性扩张且没有退出条件"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>画出框架各层及责任边界；从最小循环推导真实需求；设计可移植状态与重放测试；用质量、成本和故障恢复选择抽象层。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>先理解最小循环，再选择框架<span class=\"dd-badge intuition\">定位</span></h2><p class=\"dd-lead\">一个 Agent 的核心运行时究竟需要多少代码？</p><p>最小循环只有：组装上下文→调用模型→解析工具意图→执行工具→记录观察→判断完成或继续。框架把这些步骤产品化，并可能加入路由、检查点、人工中断和追踪。若团队不知道自己需要解决哪个具体痛点，框架只会把一个可见循环变成不可见调用栈。</p><p>智能体框架是把模型调用、工具循环、状态保存和追踪封装成运行时的开发组件。输入是已理解的最小 Agent 循环和具体工程痛点，输出是较少样板代码及可选路由、检查点和观测能力。它减少实现摩擦，不定义业务成功；需求不清时厚框架只会隐藏调用栈。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>框架通常横跨五个不同层<span class=\"dd-badge eng\">分层</span></h2><p class=\"dd-lead\">“支持 Agent”可能只支持模型接口，也可能包含持久工作流，怎样比较？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层</th><th>典型职责</th><th>不应替业务决定</th></tr></thead><tbody><tr><td>模型适配</td><td>请求、流式、工具schema</td><td>模型是否适合任务</td></tr><tr><td>运行循环</td><td>调用、工具、终止</td><td>完成条件与风险预算</td></tr><tr><td>状态/图</td><td>节点、分支、检查点</td><td>领域对象语义</td></tr><tr><td>扩展生态</td><td>连接器、记忆、插件</td><td>供应链信任</td></tr><tr><td>观测/部署</td><td>trace、队列、评测</td><td>指标是否代表真实价值</td></tr></tbody></table></div><p>框架分层输入候选产品能力，输出模型适配、运行循环、状态图、扩展生态和观测部署五层责任。逐层比较可避免把“支持 Agent”当成同一能力。层级覆盖越多不表示越适合生产，业务仍须自己拥有目标、权限、领域语义和价值指标。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>完整示例：从手写客服循环到持久状态图<span class=\"dd-badge eng\">案例推演</span></h2><p class=\"dd-lead\">什么时候“加一个框架”比继续写 if/else 更清楚？</p><p>初版客服只有“分类→查订单→回答”，手写循环最透明。后来新增：退款需人工批准、等待回调可跨天、失败后从检查点恢复、不同租户工具权限不同。此时把状态建为 <code>{case_id, intent, order, proposed_action, approval, result}</code>，用显式节点和条件边承载持久等待，框架开始提供实质价值。</p><ol class=\"dd-steps\"><li>先以两个真实案例记录手写循环的事件轨迹。</li><li>在框架中复现同一状态转移，不先加入额外功能。</li><li>中途杀进程，验证从批准前状态恢复且不重复退款。</li><li>比较原始请求、token、工具参数和最终业务状态。</li><li>保留直接调用工具和模型的降级路径。</li></ol><p>若框架版只能更漂亮地画图，却不能改善恢复或调试，就没有证明迁移价值。</p><p>客服案例输入手写循环、退款审批、跨天回调、恢复和租户权限，输出版本化领域状态与持久状态图。先复现原轨迹，再杀进程验证不重复退款并保留直接降级路径。框架版只有在恢复或诊断改善时才证明价值，图画得漂亮不是验收。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>状态属于领域，消息只是一个视图<span class=\"dd-badge eng\">状态设计</span></h2><p class=\"dd-lead\">为什么把全部业务数据塞进框架 message 列表会锁死迁移？</p><p>领域状态使用自己的版本化schema，消息从状态派生；订单ID、批准状态、证据和幂等键不应只藏在自然语言历史里。框架检查点保存状态版本与事件引用，恢复时执行迁移。这样可替换模型、消息格式或框架，而不重写业务数据库。</p><p>并发分支更新使用明确归并规则，避免全局可变字典让两个用户串状态。</p><p>领域状态设计输入订单、批准、证据、幂等键和版本，输出独立于框架消息的 schema 与迁移记录。消息从状态派生，检查点保存版本和事件引用，并发分支按明确规则归并。框架消息只是一个视图，不能成为业务唯一真相或跨租户共享字典。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：框架在领域控制与外部系统之间提供运行时<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">哪一层应该能被替换，哪一层必须由应用自己拥有？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 325\" role=\"img\" aria-label=\"领域层定义目标状态权限和验收，框架运行时提供循环图检查点和追踪，下方适配模型工具存储与队列\"><defs><marker id=\"af29\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#788293\"/></marker></defs><rect x=\"70\" y=\"30\" width=\"595\" height=\"72\" rx=\"10\" fill=\"#21252d\" stroke=\"#d3a05a\" stroke-width=\"2\"/><text x=\"367\" y=\"58\" text-anchor=\"middle\" class=\"svg-t\">应用拥有：目标 · 领域状态 · 权限 · 验收 · 风险预算</text><text x=\"367\" y=\"84\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">自有schema与测试，不绑定框架消息类型</text><path d=\"M367,102 L367,130\" stroke=\"#788293\" marker-end=\"url(#af29)\"/><rect x=\"70\" y=\"135\" width=\"595\" height=\"92\" rx=\"10\" fill=\"#21252d\" stroke=\"#8b76bd\"/><text x=\"367\" y=\"164\" text-anchor=\"middle\" class=\"svg-t\">框架运行时</text><text x=\"175\" y=\"194\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">模型/工具循环</text><text x=\"305\" y=\"194\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">状态图/路由</text><text x=\"435\" y=\"194\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">检查点/中断</text><text x=\"565\" y=\"194\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">追踪/评测钩子</text><path d=\"M175,227 L175,257\" stroke=\"#788293\" marker-end=\"url(#af29)\"/><path d=\"M305,227 L305,257\" stroke=\"#788293\" marker-end=\"url(#af29)\"/><path d=\"M435,227 L435,257\" stroke=\"#788293\" marker-end=\"url(#af29)\"/><path d=\"M565,227 L565,257\" stroke=\"#788293\" marker-end=\"url(#af29)\"/><rect x=\"105\" y=\"262\" width=\"140\" height=\"50\" rx=\"8\" fill=\"#21252d\" stroke=\"#65a6d9\"/><rect x=\"250\" y=\"262\" width=\"110\" height=\"50\" rx=\"8\" fill=\"#21252d\" stroke=\"#65a6d9\"/><rect x=\"365\" y=\"262\" width=\"140\" height=\"50\" rx=\"8\" fill=\"#21252d\" stroke=\"#65a6d9\"/><rect x=\"510\" y=\"262\" width=\"120\" height=\"50\" rx=\"8\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"175\" y=\"292\" text-anchor=\"middle\" class=\"svg-t\">模型供应商</text><text x=\"305\" y=\"292\" text-anchor=\"middle\" class=\"svg-t\">工具/API</text><text x=\"435\" y=\"292\" text-anchor=\"middle\" class=\"svg-t\">存储/队列</text><text x=\"570\" y=\"292\" text-anchor=\"middle\" class=\"svg-t\">观测后端</text></svg><figcaption>图 1　框架是可替换运行时；正确性和控制权必须留在应用拥有的领域层。</figcaption></figure><p>分层架构图输入应用领域控制、框架运行时和外部模型工具存储，输出可替换的责任边界。应用拥有目标、权限、验收和 schema，框架只承载循环、图、检查点和追踪。可替换表示接口与测试隔离良好，不表示任意框架可无损互换。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>重试、取消和终止语义必须可见<span class=\"dd-badge eng\">可靠性</span></h2><p class=\"dd-lead\">框架自动重试模型和工具，为什么可能悄悄重复副作用？</p><p>区分模型调用、只读工具和写工具的重试策略；写操作需要幂等键与结果查询。取消必须从用户请求传播到模型流、工具和子任务；达到步数、预算、无进展或完成条件时明确终止。默认无限重试会隐藏成本并制造重入。</p><p>框架应暴露每次物理尝试、退避、超时和最终状态，而不是只返回一个“失败”。</p><p>可靠性语义输入调用类型、错误、幂等键、预算和取消信号，输出重试、查询、取消或终止。模型与只读工具可按错误有界重试，写工具先查询结果并去重，取消传播到子任务。框架自动重试只表示再次调度，可能放大永久错误和副作用。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>抽象泄漏不是例外，而是调试入口<span class=\"dd-badge eng\">逃生口</span></h2><p class=\"dd-lead\">统一模型接口为什么经常遮住新能力或错误细节？</p><p>供应商在工具调用、缓存、推理、流式事件和错误码上不完全同构。最低公分母适配器会丢能力，厚封装会改写参数或消息。保留原始请求响应、供应商扩展字段、直接调用路径和可插拔适配器；业务代码不得依赖不可导出的内部对象。</p><div class=\"dd-note warn\"><b>初学者最易混淆：</b>接口统一不等于语义等价。更换适配器后必须重跑任务与安全评测。</div><p>抽象逃生口输入供应商原始请求响应、扩展字段和框架适配结果，输出可诊断差异与直接调用路径。它解决统一接口遮蔽新能力和错误细节的问题。接口一致不等于语义等价；更换适配器后必须重跑任务、安全和成本评测。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>插件与连接器扩大供应链和权限面<span class=\"dd-badge eng\">安全</span></h2><p class=\"dd-lead\">安装社区工具包为何可能等于执行第三方代码？</p><p>连接器可能读取环境变量、文件或网络，回调可修改状态，默认提示也可能注入隐藏规则。锁定版本与哈希，审查维护者、许可和依赖；在最小权限沙箱运行，工具逐项允许，并区分开发/生产凭证。升级框架时重新审计隐式默认值和迁移脚本。</p><p>插件治理输入连接器代码、依赖、权限、提示和生产凭证，输出允许、沙箱限制、版本锁定或拒绝。社区包可能读取环境、网络和文件，因此逐工具允许并审计升级默认值。安装成功或来源流行不表示供应链可信。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>选型实验要测故障，而不仅是开发速度<span class=\"dd-badge math\">决策</span></h2><p class=\"dd-lead\">框架节省两天开发，却让每月升级和故障排查增加多少成本？</p><p>对两个代表性任务做time-box试验，比较首次实现时间、任务成功、P95延迟、token/工具成本、trace覆盖、进程崩溃恢复、人工中断和升级回归。粗略总拥有成本可写为：</p><div class=\"dd-formula\" data-formula-id=\"agent-framework-tco\" data-display=\"mathml\"><math display=\"block\" aria-label=\"总拥有成本 TCO 等于初始开发、运行、故障诊断、升级迁移和供应商锁定成本之和\"><mi>TCO</mi><mo>=</mo><msub><mi>C</mi><mtext>develop</mtext></msub><mo>+</mo><msub><mi>C</mi><mtext>run</mtext></msub><mo>+</mo><msub><mi>C</mi><mtext>diagnose</mtext></msub><mo>+</mo><msub><mi>C</mi><mtext>migrate</mtext></msub><mo>+</mo><msub><mi>C</mi><mtext>lockin</mtext></msub></math></div><p class=\"dd-formula-note\"><code>TCO</code> 是选定时间范围内的总拥有成本；<code>Cdevelop</code>、<code>Crun</code>、<code>Cdiagnose</code>、<code>Cmigrate</code>、<code>Clockin</code> 分别是初始开发、日常运行、故障诊断、升级迁移和供应商锁定成本。</p><p>如果故障时无法定位到原始模型请求、工具参数和状态版本，组件丰富反而是负资产。选择满足当前必须能力的最薄层，并为退出成本设上限。</p><p>选型实验输入代表任务、候选框架和初始开发、运行、诊断、迁移、锁定五类成本，输出同预算质量、延迟、恢复和 TCO。time-box 实验注入崩溃与人工中断，并要求能定位原始请求和状态。TCO 是决策框架而非精确预测，权重和时间范围必须按团队实际估计。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">10</span>迁移靠契约测试，不靠重新看一遍 Demo<span class=\"dd-badge eng\">演进</span></h2><p class=\"dd-lead\">框架大版本升级后，哪些行为最容易悄悄变化？</p><p>冻结一组关键轨迹：输入状态、期望工具序列、权限拒绝、人工暂停、超时、恢复和最终业务状态。升级时比较事件与副作用，而非要求自然语言逐字一致。状态schema先迁移，运行中新旧实例分开；灰度观察成本、延迟和失败分布，再扩大。</p><p>迁移契约测试输入冻结的状态、工具序列、权限拒绝、人工暂停、超时、恢复和业务结果，输出旧版与新版的事件及副作用差异。先迁移 schema，再分开运行新旧实例并灰度观察。自然语言不必逐字相同，但权限、状态和副作用边界不得静默变化。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">11</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">框架降低实现摩擦，但不会降低任务本身的不确定性。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>框架越全越适合生产</td><td>多抽象也带来调试与迁移成本</td></tr><tr><td>统一接口可无缝换模型</td><td>语义与能力仍需回归</td></tr><tr><td>框架状态就是领域状态</td><td>核心对象应有自有schema</td></tr><tr><td>自动重试提高可靠性</td><td>副作用与永久错误可能被放大</td></tr><tr><td>用了框架就有可观测性</td><td>需保留原始事件与业务结果</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>Agent循环、工具调用、状态机</td></tr><tr><td><b>本页核心</b></td><td>分层、状态所有权、逃生口、契约测试</td></tr><tr><td>相邻</td><td>工作流编排、多智能体、MCP</td></tr><tr><td>工程</td><td>版本锁定、沙箱、追踪与迁移</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">12</span>自建与引入不是二选一，而是逐层购买抽象<span class=\"dd-badge eng\">架构决策</span></h2><p class=\"dd-lead\">团队需要追踪但不需要状态图，是否必须采用完整Agent框架？</p><p>按层做决策：模型SDK、工具schema、追踪、队列、持久图可以来自不同组件。先购买难以稳定自建的横切能力，例如可观测后端；保留简单领域循环。只有状态恢复、人工中断或图路由反复出现时才引入对应运行时。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>需求</th><th>最小选择</th><th>升级信号</th></tr></thead><tbody><tr><td>单轮工具调用</td><td>供应商SDK+薄封装</td><td>多模型兼容真实发生</td></tr><tr><td>多步短循环</td><td>手写循环+trace</td><td>恢复/分支难维护</td></tr><tr><td>跨天状态</td><td>持久工作流/状态图</td><td>人工任务与版本迁移</td></tr><tr><td>多角色协作</td><td>任务队列+契约</td><td>动态委派确有收益</td></tr></tbody></table></div><p>决策记录写明采用原因、被拒方案、退出条件与所有者；否则框架会因惯性而非价值不断扩张。</p><p>逐层购买抽象输入真实需求、已有组件和升级信号，输出 SDK、追踪、队列、状态图等最薄组合。先购买横切能力，只有恢复、中断或图路由反复出现才加厚运行时。混合自建与引入表示责任可拆分，不允许框架因惯性扩张且没有退出条件。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">13</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>手写最小循环暴露真实需求</li><li>列出必须能力与失败模式</li><li>选择最薄候选框架</li><li>用领域schema隔离状态</li><li>实现重试取消和权限</li><li>保留原始请求与逃生口</li><li>故障注入并比较TCO</li><li>用契约轨迹灰度升级</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">14</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>为什么先手写最小循环？</li><li>领域状态为何不能只用框架消息？</li><li>统一模型接口的主要风险？</li><li>框架自动重试为何危险？</li><li>怎样证明框架值得？</li><li>假设“智能体框架：抽象运行循环，但不外包正确性与控制权”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>先看清真实需求和失败点，避免用框架功能反向定义架构。</li><li>消息格式会变且难表达权限、版本、幂等和业务语义。</li><li>遮蔽供应商特性、错误语义与新能力，切换仍需回归。</li><li>写工具可能产生重复副作用，永久错误会被反复放大。</li><li>比较任务、成本、故障恢复、诊断和升级迁移的总拥有成本。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2308.11432\" target=\"_blank\" rel=\"noopener\">LLM Powered Autonomous Agents Survey</a>：智能体组件与挑战综述</li><li><a href=\"https://arxiv.org/abs/2308.08155\" target=\"_blank\" rel=\"noopener\">AutoGen</a>：多智能体框架设计</li><li><a href=\"https://arxiv.org/abs/2210.03629\" target=\"_blank\" rel=\"noopener\">ReAct</a>：最小推理—行动循环</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
